SELECT 
  FROM course c
 WHERE c.course_id = #{courseId}

SELECT p.place_id AS id, p.place_name AS name, cp.course_id AS courseId, cp.sort_order AS sortOrder FROM course_place cp JOIN place p ON p.place_id = cp.place_id WHERE cp.course_id IN
#{cid}
ORDER BY cp.course_id, cp.sort_order ASC, cp.course_place_id ASC

SELECT cc.course_content_id AS courseContentId, cc.language AS language, cc.course_name AS courseName, cc.description AS description, cc.course_id AS courseId FROM course_content cc WHERE cc.course_id IN
#{cid}
ORDER BY cc.course_id, cc.language, cc.course_content_id

mapper.update:
UPDATE course
   SET is_active  = FALSE,
       deleted_at = #{deletedAt},
       updated_at = #{deletedAt}
 WHERE course_id  = #{courseId}
   AND is_active  = TRUE

UPDATE course
   SET is_active  = TRUE,
       deleted_at = NULL,
       updated_at = #{updatedAt}
 WHERE course_id  = #{courseId}
   AND is_active  = FALSE
